import SwiftUI
struct PhotoCreationCard:View{ @Environment(AppModel.self) private var model;let record:PhotoGenerationRecord;var body:some View{VStack(alignment:.leading,spacing:9){Group{if let image=model.photoImage(for:record,thumbnail:true){Image(uiImage:image).resizable().scaledToFit()}else{Color.white}}.aspectRatio(1,contentMode:.fit).clipShape(RoundedRectangle(cornerRadius:20));Text("Photo coloring page").font(.headline);Text(record.createdAt,style:.date).font(.caption).foregroundStyle(.secondary)}}}
struct PhotoResultView:View{@Environment(AppModel.self) private var model;@Environment(\.dismiss) private var dismiss;let record:PhotoGenerationRecord;@State private var editor:ColoringProject?;@State private var retry=false;var body:some View{NavigationStack{VStack(spacing:18){if let image=model.photoImage(for:record,thumbnail:false){Image(uiImage:image).resizable().scaledToFit().clipShape(RoundedRectangle(cornerRadius:24))};Text("Photo coloring page").font(.title2.bold());Button{editor=model.makeProject(for:record.page)}label:{Label(model.project(for:record.page.id)==nil ? "Start Coloring":"Continue Coloring",systemImage:"paintbrush.fill").frame(maxWidth:.infinity).padding().background(Color.artInk,in:Capsule()).foregroundStyle(.white)};Button("Try Again or Adjust Style"){model.resetPhotoGeneration();retry=true};Spacer()}.padding().background(Color.artPaper).toolbar{ToolbarItem(placement:.topBarTrailing){Button("Done"){dismiss()}}}}.sheet(isPresented:$retry){PhotoCreateView(initialPrepared:model.restorePrepared(record),initialOptions:record.options)}.fullScreenCover(item:$editor){project in EditorLoaderView(page:record.page,project:project)}}}
